import test from 'node:test';
import assert from 'node:assert/strict';
import * as egret from '@egret/engine';
import { host } from './helpers.mjs';

// Original literal data, not an oracle generated by the controller or sampler.
const RED = Object.freeze({ x: 0, y: 0, width: 2, height: 2 });
const GREEN = Object.freeze({ x: 2, y: 0, width: 1, height: 2 });
const BLUE = Object.freeze({ x: 3, y: 0, width: 3, height: 1 });
const FULL = Object.freeze({ x: 0, y: 0, width: 6, height: 2 });
const PIXELS = Object.freeze([
  255,0,0,255, 255,0,0,255, 0,255,0,255, 0,0,255,255, 0,0,255,255, 0,0,255,255,
  255,0,0,255, 255,0,0,255, 0,255,0,255, 0,0,0,255, 0,0,0,255, 0,0,0,255,
]);
const FRAME = Object.freeze({ width: 8, height: 4, clearColor: 0, clearAlpha: 0 });

function expectCode(action, code, expectedCause) {
  const checkCause = arguments.length === 3;
  let actual;
  assert.throws(action, error => {
    actual = error; assert.equal(error.code, code);
    if (checkCause) assert.equal(error.cause, expectedCause);
    return true;
  });
  return actual;
}
async function scene() {
  const port = host(), diagnostics = [];
  const engine = await egret.createEngine({ host: port.adapter, clock: { maxDeltaSeconds: 0.5 },
    onDiagnostic(diagnostic) { diagnostics.push(diagnostic); } });
  try {
    const resources = engine.createScope(), scope = engine.createScope();
    const pixels = new Uint8Array(PIXELS);
    const image = egret.createImageData2D({ width: 6, height: 2, pixels });
    const texture = egret.createTexture(image); let loads = 0, disposals = 0;
    const type = egret.createAssetType('sequence-playback-lifecycle-atlas', egret.isTexture);
    engine.assets.register(type, { async load() { loads++; return texture; },
      dispose(value) { disposals++; value.dispose(); } });
    const ref = egret.createAssetRef(type, 'sequence-playback-lifecycle-image');
    const lease = resources.use(await engine.assets.acquire(ref));
    const bitmap = resources.use(new egret.Bitmap(lease)); engine.stage.addChild(bitmap);
    const input = { atlasWidth: 6, atlasHeight: 2, frames: [
      { ...RED, durationSeconds: 0.125 }, { ...GREEN, durationSeconds: 0.25 },
      { ...BLUE, durationSeconds: 0.125 },
    ] };
    const clip = egret.createSequenceClip(input);
    const manual = new egret.SequencePlayer(bitmap, clip);
    try { assert.deepEqual(manual.applyAt(0), {
      frameIndex: 0, region: RED, positionSeconds: 0, atEnd: false, stopped: false,
    }); } finally { manual.dispose(); }
    assert.equal(engine.captureFrame(FRAME).images[0], image);
    assert.equal(port.timers.size, 0);
    assert.equal(typeof engine.createSequencePlayback, 'function', 'SEQUENCE_PLAYBACK_FACTORY_REQUIRED');
    return { port, engine, resources, scope, pixels, image, texture, ref, lease, bitmap,
      input, clip, diagnostics, counts: () => ({ loads, disposals }) };
  } catch (cause) { await engine.dispose(); throw cause; }
}
async function close(f) {
  await f.engine.dispose();
  assert.deepEqual(f.port.trace, ['start', 'stop', 'close']);
  assert.equal(f.port.timers.size, 0);
  assert.deepEqual(f.counts(), { loads: 1, disposals: 1 });
}
function playback(f, options, scope = f.scope, bitmap = f.bitmap) {
  return f.engine.createSequencePlayback(scope, bitmap, f.clip, options);
}
function sample(index, region, position, atEnd = false) {
  return { frameIndex: index, region, positionSeconds: position, atEnd, stopped: false };
}
function oneClockDiagnostic(f, cause) {
  assert.equal(f.diagnostics.length, 1);
  assert.equal(f.diagnostics[0].code, 'CLOCK_CALLBACK_FAILED');
  assert.equal(f.diagnostics[0].phase, 'engine');
  assert.equal(f.diagnostics[0].severity, 'error');
  assert.equal(f.diagnostics[0].cause, cause);
}

// L03: a foreign callback commits the clock but cannot replay the skipped player.
test('SQL01 earlier callback failure preserves time commit without equal-source replay', async () => {
  const f = await scene(); const sentinel = Object.freeze({ witness: 'SQL01 literal cause' });
  try {
    const earlier = f.engine.clock.onTick(f.resources, () => { throw sentinel; });
    const p = playback(f); p.start(); f.engine.advanceTime(10);
    const held = p.lastSample;
    expectCode(() => f.engine.advanceTime(10.125), 'CLOCK_CALLBACK_FAILED', sentinel);
    oneClockDiagnostic(f, sentinel);
    assert.equal(f.engine.clock.elapsedSeconds, 0.125); assert.equal(f.engine.clock.tickId, 1);
    assert.equal(p.state, 'running'); assert.equal(p.elapsedSeconds, 0); assert.equal(p.lastSample, held);
    assert.equal(f.engine.advanceTime(10.125), undefined); assert.equal(p.lastSample, held);
    earlier.dispose(); f.engine.advanceTime(10.25);
    assert.equal(p.elapsedSeconds, 0.25); assert.deepEqual(p.lastSample, sample(1, GREEN, 0.25));
    assert.equal(f.diagnostics.length, 1);
  } finally { await close(f); }
});

// L04: each assigned ordinary resource mutation has a fresh valid running baseline.
test('SQL02 exact binding and entitlement failures terminalize before the clock reports once', async t => {
  const cases = [
    { name: 'released-exact-lease', code: 'ASSET_LEASE_RELEASED', mutate: async f => { f.lease.release(); } },
    { name: 'disposed-texture', code: 'TEXTURE_DISPOSED', mutate: async f => { f.texture.dispose(); } },
    { name: 'disposed-bitmap', code: 'OBJECT_DISPOSED', mutate: async f => { f.bitmap.dispose(); } },
    { name: 'different-lease-same-texture', code: 'SEQ_BINDING_CHANGED', mutate: async f => {
      const other = f.resources.use(await f.engine.assets.acquire(f.ref));
      assert.equal(other.value, f.texture); f.bitmap.textureLease = other; f.lease.release();
    } },
    { name: 'cleared-slot-before-entitlement', code: 'SEQ_BINDING_CHANGED', mutate: async f => {
      f.bitmap.textureLease = undefined; f.lease.release();
    } },
  ];
  for (const witness of cases) await t.test(witness.name, async () => {
    const f = await scene();
    try {
      const p = playback(f); p.start(); f.engine.advanceTime(10);
      const held = p.lastSample; assert.deepEqual(held, sample(0, RED, 0));
      await witness.mutate(f);
      const outer = expectCode(() => f.engine.advanceTime(10.125), 'CLOCK_CALLBACK_FAILED');
      assert.equal(outer.cause.code, witness.code); oneClockDiagnostic(f, outer.cause);
      assert.equal(p.state, 'failed'); assert.equal(p.isDisposed, true);
      assert.equal(p.elapsedSeconds, 0); assert.equal(p.lastSample, held);
      assert.equal(f.engine.advanceTime(10.125), undefined);
      f.engine.advanceTime(10.25); assert.equal(p.lastSample, held); assert.equal(f.diagnostics.length, 1);
      p.stop(); p.dispose(); assert.equal(p.state, 'failed');
    } finally { await close(f); }
  });
});

// Resume's live resource check is immediate and its failed registration leaves no slot.
test('SQL03 paused lease loss fails resume directly and releases the attempted subscription', async () => {
  const f = await scene();
  try {
    const p = playback(f); p.start(); p.pause(); const held = p.lastSample;
    f.lease.release(); expectCode(() => p.resume(), 'ASSET_LEASE_RELEASED');
    assert.equal(p.state, 'failed'); assert.equal(p.lastSample, held); assert.equal(p.elapsedSeconds, 0);
    assert.deepEqual(f.diagnostics, []);
    const all = Array.from({ length: 256 }, () => f.engine.clock.onTick(f.resources, () => undefined));
    assert.equal(all.length, 256);
  } finally { await close(f); }
});

// Exact same-lease assignment may reset crop; the next tick reasserts the owned frame.
test('SQL04 same lease, manual crop and generation invalidation preserve the existing borrow', async () => {
  const f = await scene();
  try {
    const p = playback(f); p.start(); f.engine.advanceTime(10);
    f.bitmap.textureLease = f.lease; assert.deepEqual(f.bitmap.sourceRect, FULL);
    f.engine.assets.invalidate(f.ref); f.bitmap.sourceRect = BLUE;
    f.engine.advanceTime(10.125);
    assert.deepEqual(p.lastSample, sample(1, GREEN, 0.125));
    assert.deepEqual(f.bitmap.sourceRect, GREEN); assert.equal(f.bitmap.textureLease, f.lease);
    assert.equal(f.lease.value, f.texture); assert.deepEqual(f.counts(), { loads: 1, disposals: 0 });
    assert.deepEqual(f.diagnostics, []);
  } finally { await close(f); }
});

// Stop owns neither the image lease nor the Bitmap; saved values survive all retirement.
test('SQL05 immutable sample/frame and caller resources survive controller stop and input changes', async () => {
  const f = await scene();
  try {
    const p = playback(f); p.start(); f.engine.advanceTime(10); f.engine.advanceTime(10.125);
    const held = p.lastSample, frame = f.engine.captureFrame(FRAME);
    assert.deepEqual(held, sample(1, GREEN, 0.125));
    p.stop(); p.dispose(); assert.equal(p.state, 'stopped'); assert.equal(p.isDisposed, true);
    assert.equal(p.lastSample, held); assert.equal(p.elapsedSeconds, 0.125);
    assert.equal(f.lease.value, f.texture); assert.equal(f.texture.isDisposed, false);
    f.pixels.fill(17); f.input.frames[1].x = 999; f.input.frames[1].durationSeconds = 99;
    f.bitmap.sourceRect = BLUE;
    assert.deepEqual(held, sample(1, GREEN, 0.125));
    assert.deepEqual(frame.commands[0].sourceRect, GREEN);
    assert.deepEqual(frame.commands[0].rect, { x: 0, y: 0, width: 1, height: 2 });
    assert.equal(frame.images[0], f.image); assert.deepEqual([...egret.copyImageData2DPixels(frame.images[0])], PIXELS);
    await f.engine.dispose();
    assert.deepEqual(held, sample(1, GREEN, 0.125));
    assert.deepEqual([...egret.copyImageData2DPixels(frame.images[0])], PIXELS);
    assert.equal(p.lastSample, held); assert.deepEqual(f.diagnostics, []);
  } finally { await close(f); }
});

// A stopped old record cannot delete a replacement target claim during historical cleanup.
test('SQL06 same-target claims reject concurrent handles and remain identity-specific after old Scope close', async () => {
  const f = await scene();
  try {
    const old = playback(f); old.start();
    expectCode(() => playback(f), 'SEQ_PLAYBACK_TARGET_BUSY');
    old.pause(); expectCode(() => playback(f), 'SEQ_PLAYBACK_TARGET_BUSY');
    old.stop(); const newerScope = f.engine.createScope();
    const newer = playback(f, { mode: 'loop' }, newerScope); newer.start();
    f.scope.dispose(); assert.equal(old.state, 'stopped'); assert.equal(newer.state, 'running');
    expectCode(() => playback(f, undefined, newerScope), 'SEQ_PLAYBACK_TARGET_BUSY');
    f.engine.advanceTime(10); f.engine.advanceTime(10.125);
    assert.deepEqual(newer.lastSample, sample(1, GREEN, 0.125));
    newerScope.dispose(); assert.equal(newer.state, 'stopped');
    const again = playback(f, undefined, f.resources); assert.equal(again.state, 'idle'); again.stop();
    assert.equal(f.lease.value, f.texture); assert.deepEqual(f.diagnostics, []);
  } finally { await close(f); }
});

// L05: cancellation enters closing before reverse cleanup; old candidates must not write.
test('SQL07 a Scope abort listener can reach a tick while closing without reviving its player', async () => {
  const f = await scene();
  try {
    const p = playback(f); p.start(); f.engine.advanceTime(10); const held = p.lastSample;
    f.bitmap.sourceRect = BLUE;
    let reached = 0, stateSeen, tick;
    f.scope.signal.addEventListener('abort', () => {
      reached++; stateSeen = f.scope.state; tick = f.engine.advanceTime(10.125);
    });
    f.scope.dispose();
    assert.equal(reached, 1); assert.equal(stateSeen, 'closing');
    assert.deepEqual(tick, { tickId: 1, elapsedSeconds: 0.125, deltaSeconds: 0.125 });
    assert.equal(p.state, 'stopped'); assert.equal(p.lastSample, held); assert.equal(p.elapsedSeconds, 0);
    assert.deepEqual(f.bitmap.sourceRect, BLUE); assert.equal(f.lease.value, f.texture);
    assert.deepEqual(f.diagnostics, []);
  } finally { await close(f); }
});

// L06: Engine closure stops idle/running/paused before later dispatch candidates.
test('SQL08 earlier callback Engine disposal preserves the tick and prevents later animation writes', async () => {
  const f = await scene();
  try {
    let closing, observed;
    const idleTarget = f.resources.use(new egret.Bitmap(f.lease));
    const pausedTarget = f.resources.use(new egret.Bitmap(f.lease));
    let idle, running, paused;
    f.engine.clock.onTick(f.resources, () => {
      closing = f.engine.dispose();
      observed = [idle.state, running.state, paused.state, f.engine.clock.state];
      return undefined;
    });
    idle = playback(f, undefined, f.scope, idleTarget);
    running = playback(f); running.start();
    paused = playback(f, undefined, f.scope, pausedTarget); paused.start(); paused.pause();
    const held = running.lastSample; f.engine.advanceTime(10);
    const tick = f.engine.advanceTime(10.125);
    assert.deepEqual(tick, { tickId: 1, elapsedSeconds: 0.125, deltaSeconds: 0.125 });
    assert.deepEqual(observed, ['stopped', 'stopped', 'stopped', 'closed']);
    assert.equal(running.lastSample, held); assert.equal(running.elapsedSeconds, 0);
    await closing;
    for (const p of [idle, running, paused]) {
      assert.equal(p.isDisposed, true); p.stop(); p.dispose();
      expectCode(() => p.start(), 'ENGINE_CLOSED');
    }
    assert.equal(f.engine.clock.elapsedSeconds, 0.125); assert.deepEqual(f.diagnostics, []);
  } finally { await close(f); }
});

// Existing clock/frame reentrancy is checked before reading a new frame payload.
test('SQL09 same-Engine nested time/frame calls stay refused while a controller tick is pending', async () => {
  const f = await scene();
  try {
    let reads = 0, reached = 0;
    f.engine.clock.onTick(f.resources, () => {
      reached++;
      expectCode(() => f.engine.advanceTime(-1), 'CLOCK_REENTRANT');
      expectCode(() => f.engine.captureFrame({ get width() { reads++; return 8; } }), 'CLOCK_REENTRANT');
      return undefined;
    });
    const p = playback(f); p.start(); f.engine.advanceTime(10); f.engine.advanceTime(10.125);
    assert.equal(reached, 1); assert.equal(reads, 0);
    assert.deepEqual(p.lastSample, sample(1, GREEN, 0.125)); assert.deepEqual(f.diagnostics, []);
  } finally { await close(f); }
});

// Authentic Scope membership precedes options, and facade receivers never become authority.
test('SQL10 same-Engine Scope and opaque receiver checks precede control payloads', async () => {
  const f = await scene(), other = await scene();
  try {
    let reads = 0;
    const unread = { get mode() { reads++; return 'once'; } };
    for (const badScope of [{}, new Proxy(f.scope, {}), other.scope]) {
      expectCode(() => f.engine.createSequencePlayback(badScope, f.bitmap, f.clip, unread), 'SEQ_PLAYBACK_SCOPE_INVALID');
    }
    assert.equal(reads, 0);
    const p = playback(f), query = Object.getOwnPropertyDescriptor(p, 'state').get;
    for (const fake of [undefined, null, 1, {}, { ...p }, new Proxy(p, {})]) {
      expectCode(() => Reflect.apply(query, fake, []), 'SEQ_PLAYBACK_INVALID');
      for (const method of ['start', 'pause', 'resume', 'stop', 'dispose']) {
        expectCode(() => Reflect.apply(p[method], fake, []), 'SEQ_PLAYBACK_INVALID');
      }
    }
    for (const key of ['player', 'bitmap', 'lease', 'clip', 'clock', 'scope', 'owner', 'subscription']) {
      assert.equal(key in p, false);
    }
    p.stop(); f.scope.dispose();
    expectCode(() => playback(f, unread), 'SCOPE_CLOSED'); assert.equal(reads, 0);
    expectCode(() => p.start(), 'SCOPE_CLOSED'); p.stop(); p.dispose();
    assert.deepEqual(f.diagnostics, []); assert.deepEqual(other.diagnostics, []);
  } finally { await close(f); await close(other); }
});

// Public clock and Bitmap shadows supply no private timing, lease or crop authority.
test('SQL11 public clock shadows and Bitmap getter overrides stay unread during playback', async () => {
  const f = await scene();
  const clockDescriptor = Object.getOwnPropertyDescriptor(f.engine, 'clock');
  let reads = 0;
  try {
    Object.defineProperty(f.engine, 'clock', { configurable: true, value: {
      get elapsedSeconds() { reads++; throw new Error('public clock read'); },
      onTick() { reads++; throw new Error('public clock subscription'); },
    } });
    Object.defineProperty(f.bitmap, 'textureLease', { configurable: true, get() { reads++; throw new Error('public lease read'); } });
    Object.defineProperty(f.bitmap, 'sourceRect', { configurable: true, get() { reads++; throw new Error('public crop read'); } });
    const p = playback(f); p.start(); p.pause(); p.resume();
    f.engine.advanceTime(10); f.engine.advanceTime(10.125);
    assert.deepEqual(p.lastSample, sample(1, GREEN, 0.125));
    assert.deepEqual(f.engine.captureFrame(FRAME).commands[0].sourceRect, GREEN);
    assert.equal(reads, 0); assert.deepEqual(f.diagnostics, []);
  } finally {
    Object.defineProperty(f.engine, 'clock', clockDescriptor);
    delete f.bitmap.textureLease; delete f.bitmap.sourceRect;
    await close(f);
  }
});

// L09/SEQP-D01: patch only after captures; live and historical Scope cleanup must
// use the private player's sealed own operation while caller resources stay live.
test('SQL12 captured player operations and sealed own cleanup never call patched prototypes', async () => {
  const f = await scene();
  const proto = egret.SequencePlayer.prototype;
  const applyDescriptor = Object.getOwnPropertyDescriptor(proto, 'applyAt');
  const disposeDescriptor = Object.getOwnPropertyDescriptor(proto, 'dispose');
  let applySpies = 0, disposeSpies = 0;
  const sentinel = Object.freeze({ witness: 'SQL12 prototype spy must stay unreachable' });
  try {
    Object.defineProperty(proto, 'applyAt', { ...applyDescriptor, value() { applySpies++; throw sentinel; } });
    Object.defineProperty(proto, 'dispose', { ...disposeDescriptor, value() { disposeSpies++; throw sentinel; } });
    const old = playback(f); old.start(); old.pause(); old.resume(); old.stop();
    const nextScope = f.engine.createScope();
    const next = playback(f, { mode: 'loop' }, nextScope); next.start();
    f.scope.dispose();
    assert.equal(old.state, 'stopped'); assert.equal(old.isDisposed, true); assert.equal(next.state, 'running');
    expectCode(() => playback(f, undefined, nextScope), 'SEQ_PLAYBACK_TARGET_BUSY');
    f.engine.advanceTime(10); f.engine.advanceTime(10.125);
    assert.deepEqual(next.lastSample, sample(1, GREEN, 0.125));
    nextScope.dispose(); assert.equal(next.state, 'stopped');
    assert.deepEqual([applySpies, disposeSpies], [0, 0]);
    assert.equal(f.lease.value, f.texture); assert.equal(f.texture.isDisposed, false);
    assert.deepEqual(f.engine.captureFrame(FRAME).commands[0].sourceRect, GREEN);
    assert.deepEqual(f.diagnostics, []);
    const finalScope = f.engine.createScope();
    const final = playback(f, undefined, finalScope); final.start();
    await f.engine.dispose(); assert.equal(final.state, 'stopped');
    assert.deepEqual([applySpies, disposeSpies], [0, 0]); assert.deepEqual(f.diagnostics, []);
  } finally {
    Object.defineProperty(proto, 'applyAt', applyDescriptor);
    Object.defineProperty(proto, 'dispose', disposeDescriptor);
    await close(f);
  }
});
